<?php
require_once __DIR__ . '/../app/application.php';requirePermission('contracts.manage');$id=(int)($_GET['id']??0);$lang=validateChoice($_GET['lang']??'',supportedLanguages(),'fr');$contract=dbFetchOne('SELECT rc.*,r.agency_id,cv.snapshot_json,cv.terms_text,cv.version_number FROM rental_contracts rc JOIN reservations r ON r.id=rc.reservation_id JOIN contract_versions cv ON cv.contract_id=rc.id AND cv.version_number=rc.current_version WHERE rc.id=:id AND cv.language_code=:lang',['id'=>$id,'lang'=>$lang]);if(!$contract){$contract=dbFetchOne('SELECT rc.*,r.agency_id,cv.snapshot_json,cv.terms_text,cv.version_number FROM rental_contracts rc JOIN reservations r ON r.id=rc.reservation_id JOIN contract_versions cv ON cv.contract_id=rc.id AND cv.version_number=rc.current_version WHERE rc.id=:id ORDER BY cv.id LIMIT 1',['id'=>$id]);}if(!$contract){http_response_code(404);exit('Contract not found.');}requireAgencyAccess($contract['agency_id']);$data=json_decode($contract['snapshot_json'],true);?><!doctype html><html lang="<?=e($lang)?>" dir="<?=$lang==='ar'?'rtl':'ltr'?>"><head><meta charset="utf-8"><title><?=e($contract['contract_number'])?></title><style>body{font:14px Arial;max-width:900px;margin:30px auto;color:#172536}header{display:flex;justify-content:space-between;border-bottom:3px solid #143b61;padding-bottom:20px}h1{color:#143b61}section{margin:25px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.box{border:1px solid #ccd7e0;padding:15px}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:50px;margin-top:70px}.signature{border-top:1px solid #333;padding-top:8px}@media print{button{display:none}body{margin:0}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button><header><div><h1>Rental contract</h1><strong><?=e(appConfig('name'))?></strong></div><div><strong><?=e($contract['contract_number'])?></strong><br>Version <?=e($contract['version_number'])?><br><?=e($contract['status'])?></div></header><section class="grid"><div class="box"><h2>Customer</h2><p><?=e($data['customer']['name']??'')?></p><p>Identity: <?=e($data['customer']['identity_number']??'')?></p><p>Licence: <?=e($data['customer']['licence_number']??'')?></p></div><div class="box"><h2>Vehicle</h2><p><?=e($data['vehicle']['description']??'')?></p><p>Registration: <?=e($data['vehicle']['registration_number']??'')?></p><p>VIN: <?=e($data['vehicle']['vin']??'')?></p></div></section><section class="box"><h2>Rental</h2><p>Pickup: <?=e($data['period']['pickup_at']??'')?></p><p>Return: <?=e($data['period']['return_at']??'')?></p><p>Total: <?=money($data['pricing']['total']??0,$data['currency']??'MAD')?></p><p>Deposit: <?=money($data['deposit_amount']??0,$data['currency']??'MAD')?></p></section><section><h2>Terms</h2><p><?=nl2br(e($contract['terms_text']))?></p></section><div class="signatures"><div class="signature">Customer signature</div><div class="signature">Agency signature</div></div></body></html>
